	private static void assertPhysical(Observed result) {
		Map<List<Value>, Long> expected = new LinkedHashMap<>();
		for (long subject = 1L; subject <= ROWS; subject++) {
			expected.put(List.of(value(subject), value(1_000L + subject)), 1L);
		}
		assertThat(result.bag()).isEqualTo(expected);
		assertThat(result.visited()).as("the same32 matching records in every predicate")
				.containsExactly(0, ROWS, ROWS, ROWS);
		assertThat(result.opened()).as("one root open and two tail opens for every subject").isEqualTo(1 + 2 * ROWS);
		assertThat(result.closed()).isEqualTo(result.opened());
	}

