	/** Real records support the exact source-entry proof; the added predicate is outside every query lookup. */
	private static final class Source implements NativeLmdbQuerySource {
		final List<long[]> data = new ArrayList<>();
		final Map<Long, List<long[]>> predicates = new LinkedHashMap<>();
		final int[] visited = new int[4];
		int opened, closed;

		Source(long entries) {
			for (long subject = 1L; subject <= ROWS; subject++) {
				for (long predicate = 1L; predicate <= 3L; predicate++) {
					add(new long[] { subject, predicate, 1_000L * predicate + subject, 0L });
				}
			}
			while (data.size() < entries) {
				long index = data.size();
				add(new long[] { 1_000_000L + index, 4L, 2_000_000L + index, 0L });
			}
			assertThat(data).hasSize(Math.toIntExact(entries));
		}

		private void add(long[] quad) {
			data.add(quad);
			predicates.computeIfAbsent(quad[1], ignored -> new ArrayList<>()).add(quad);
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public Value lazyValue(long id) {
			return value(id);
		}

		@Override
		public long idOf(Value value) {
			return value.stringValue().startsWith(NS)
					? Long.parseLong(value.stringValue().substring(NS.length()))
					: UNKNOWN_ID;
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return coveringProfile(data.size());
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			return predicate >= 1L && predicate <= 3L ? OptionalDouble.of(1D) : OptionalDouble.empty();
		}

		@Override
		public OptionalDouble distinctFanOutKeys(long predicate, boolean bySubject) {
			return predicate >= 1L && predicate <= 3L ? OptionalDouble.of(ROWS) : OptionalDouble.empty();
		}

		@Override
		public OptionalLong adjacencyKeyDomainCardinality(long predicate, boolean bySubject) {
			return predicate >= 1L && predicate <= 3L ? OptionalLong.of(ROWS) : OptionalLong.empty();
		}

		private List<long[]> matching(long s, long p, long o, long c) {
			return (p == UNKNOWN_ID ? data : predicates.getOrDefault(p, List.of())).stream()
					.filter(q -> (s == UNKNOWN_ID || s == q[0]) && (o == UNKNOWN_ID || o == q[2])
							&& (c == UNKNOWN_ID || c == q[3]))
					.toList();
		}

		@Override
		public RecordIterator statements(long s, long p, long o, long c) {
			assertThat(p).isBetween(1L, 3L);
			opened++;
			List<long[]> records = matching(s, p, o, c);
			return new RecordIterator() {
				int at;
				boolean done;

				@Override
				public long[] next() {
					if (at == records.size()) {
						return null;
					}
					visited[(int) p]++;
					return records.get(at++);
				}

				@Override
				public void close() {
					if (!done) {
						done = true;
						closed++;
					}
				}
			};
		}

		@Override
		public long count(long s, long p, long o, long c) {
			return matching(s, p, o, c).size();
		}

		@Override
		public double estimate(long s, long p, long o, long c) {
			return matching(s, p, o, c).size();
		}

		@Override
		public boolean has(long s, long p, long o, long c) throws IOException {
			try (RecordIterator iterator = statements(s, p, o, c)) {
				return iterator.next() != null;
			}
		}
	}
